collectionTypes.forEach(type=>D[type].forEach(r=>records.set(keyOf(type,r.id),{type,r})));
const searchIndex = Array.from(records.values()).map(x=>({...x,short:(title(x.r)+' '+x.r.id).toLowerCase(),search:JSON.stringify(x.r).replace(/<[^>]+>/g,' ').toLowerCase()}));
const STORE = 'aperture-review-d1-'+D.fingerprint.slice(0,12);
const newReview = () => ({schema:'aperture-review-d1',baseline:D.fingerprint,reviewer:'',entries:{},updated_at:null,revision:null});
let review=newReview(),persistent=false,storageRevision=null,storageConflict=false,invalidSaved=null;
let filters={},view='overview',activeRecord=null,tour=-1,detailTrail=[],lastRoute='',skipRouteGuard=false,dirty=false,dark=false,toastTimer=null,searchFocus=0,searchResults=[],lastFocus=null;
const PAGE=20;
function validateReview(raw){
 if(!raw || typeof raw!=='object' || Array.isArray(raw) || raw.schema!=='aperture-review-d1' || raw.baseline!==D.fingerprint)throw Error('This review packet belongs to a different schema or source baseline.');
 if(typeof raw.reviewer!=='string' || raw.reviewer.length>120 || !raw.entries || Array.isArray(raw.entries)||typeof raw.entries!=='object')throw Error('The review packet has an invalid structure.');
 const result=newReview(); result.reviewer=raw.reviewer;
 const entries=Object.entries(raw.entries);if(entries.length>records.size)throw Error('Too many review records.');
 for(const [key,v] of entries){
  if(!records.has(key) || !v || typeof v!=='object'||Array.isArray(v))throw Error('Unknown review record: '+key);
  if(!['Unreviewed','Reviewed','Follow-up'].includes(v.status)||!['Normal','High','Low'].includes(v.priority)||typeof v.note!=='string'||v.note.length>6000||typeof v.owner!=='string'||v.owner.length>120||!Array.isArray(v.checks)||v.checks.length>100||!v.checks.every(x=>Number.isInteger(x)&&x>=0&&x<100))throw Error('Invalid annotation for '+key);
  const {type,r}=records.get(key);if(v.checks.length && (type!=='sops'||v.checks.some(i=>i>=r.procedure.length)))throw Error('Invalid rehearsal steps.');
  if(v.updated_at!==null&&(typeof v.updated_at!=='string'||!Number.isFinite(Date.parse(v.updated_at))))throw Error('Invalid annotation timestamp.');
  result.entries[key]={status:v.status,priority:v.priority,note:v.note,owner:v.owner,checks:[...new Set(v.checks)],updated_at:v.updated_at};
 }
 if(raw.revision!==null && (typeof raw.revision!=='string'||raw.revision.length>120))throw Error('Invalid review revision.');
 if(raw.updated_at!==null && (typeof raw.updated_at!=='string'||!Number.isFinite(Date.parse(raw.updated_at))))throw Error('Invalid review timestamp.');
 result.updated_at=raw.updated_at;result.revision=raw.revision;return result;
}
try{const saved=localStorage.getItem(STORE);if(saved){try{review=validateReview(JSON.parse(saved));persistent=true;storageRevision=review.revision;}catch(e){invalidSaved=saved;}}}catch(e){}
function revision(){return typeof crypto.randomUUID==='function'?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`;}
function mutateReview(mutator){
 if(storageConflict){toast('Another tab changed the saved review. Reload it before writing.');return false;}
 const next=validateReview(JSON.parse(JSON.stringify(review)));mutator(next);next.updated_at=new Date().toISOString();next.revision=revision();
 try{validateReview(next);}catch(error){toast('Review not saved: '+error.message);return false;}
 if(persistent){try{const current=localStorage.getItem(STORE);const currentRevision=current?JSON.parse(current).revision:null;if(currentRevision!==storageRevision){storageConflict=true;render();toast('Saved review changed in another tab. No annotation was overwritten.');return false;}localStorage.setItem(STORE,JSON.stringify(next));storageRevision=next.revision;}catch(e){persistent=false;toast('Local storage is unavailable. This review remains in memory; export it before closing.');}}
 review=next;updateNav();return true;
}
const annotation=key=>review.entries[key]||{status:'Unreviewed',priority:'Normal',note:'',owner:'',checks:[],updated_at:null};
function pin(type,id){const key=keyOf(type,id);if(!records.has(key))return;const savedNote=review.entries[key];if(savedNote&&(savedNote.note||savedNote.owner||savedNote.checks.length||savedNote.status!=='Unreviewed')&&!confirm('Remove this record and its saved annotations from the review board? Source records and exported copies are unchanged.'))return;if(mutateReview(next=>{if(next.entries[key])delete next.entries[key];else next.entries[key]={...annotation(key)};})){toast(review.entries[key]?'Added to your review board.':'Removed from your review board.');if(activeRecord && key===keyOf(activeRecord.type,activeRecord.id))renderDetail(activeRecord.type,activeRecord.id);render(true);}}
function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,4800);}
function note(text,tone=''){return `<div class="note ${tone}">${ic('info')}<div>${text}</div></div>`;}
const pill=(text,tone='')=>`<span class="pill ${tone}">${E(text)}</span>`;
function statusPill(status){let tone='';if(/proposed|pending|not.run|not implemented|blocked|open design|follow-up|reconsider/i.test(status))tone='amber';else if(/^pass$|executed|reviewed/i.test(status))tone='green';else if(/snapshot|fixture|historical|declared/i.test(status))tone='blue';return pill(status,tone);}
function goButton(route,label,icon='arrow',cls=''){return `<button class="btn ${cls}" data-action="navigate" data-route="${E(route)}">${E(label)}${ic(icon)}</button>`;}
function openButton(type,id,label,cls='text-link'){return `<button class="${cls}" data-action="open" data-type="${E(type)}" data-id="${E(id)}">${E(label)}${cls==='text-link'?ic('arrow'):''}</button>`;}
function sourceLink(path,label='Open source document',cls='btn small'){
 if(!path)return '';
 const isRemote=/^https:\/\//.test(path);
 if(!isRemote && (/^(?:[./]*\.\.|\/\/|javascript:|data:)/i.test(path)||path.startsWith('/')))return '';
 return `<a class="${cls}" href="${E(isRemote?path:'documentation/'+path)}" target="_blank" rel="noopener noreferrer">${E(label)}${ic('up')}</a>`;
}
function head(eyebrow,heading,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">${E(eyebrow)}</div><h1>${E(heading)}</h1><p>${E(subtitle)}</p></div><div class="actions">${actions}</div></div>`;}
