const valueText=v=>Array.isArray(v)?v.join(', '):typeof v==='object'?JSON.stringify(v):String(v??'');
function getFiltered(type){const f=filters[type]||{q:'',a:'',b:'',sort:'id',page:1};const c=cfg[type]||{};let a=D[type].filter(r=>{if(f.a&&valueText(r[c.filter])!==f.a)return false;if(f.b&&valueText(r[c.second])!==f.b)return false;if(f.q&&!JSON.stringify(r).replace(/<[^>]+>/g,' ').toLowerCase().includes(f.q.toLowerCase()))return false;return true;});a.sort((x,y)=>String(f.sort==='title'?title(x):x.id).localeCompare(String(f.sort==='title'?title(y):y.id),undefined,{numeric:true}));return a;}
function filterSelect(type,field,label,key){if(!field)return '';const options=[...new Set(D[type].map(r=>valueText(r[field])))].filter(Boolean).sort();const f=filters[type]||{};return `<label class="sr-only" for="filter-${key}">${E(label)}</label><select id="filter-${key}" data-filter="${key}" data-type="${type}" aria-label="${E(label)}"><option value="">All ${E(label.toLowerCase())}</option>${options.map(v=>`<option value="${E(v)}" ${f[key]===v?'selected':''}>${E(v)}</option>`).join('')}</select>`;}
function toolbar(type){const f=filters[type]||{};const c=cfg[type]||{};return `<div class="toolbar"><label class="search-field" for="catalogSearch">${ic('search')}<span class="sr-only">Search this catalog</span><input type="search" id="catalogSearch" placeholder="Search this catalog…" value="${E(f.q||'')}" data-filter="q" data-type="${type}" autocomplete="off"></label>${filterSelect(type,c.filter,(c.filter||'').replace(/_/g,' '),'a')}${filterSelect(type,c.second,(c.second||'').replace(/_/g,' '),'b')}<select id="filter-sort" data-filter="sort" data-type="${type}" aria-label="Sort catalog"><option value="id" ${f.sort!=='title'?'selected':''}>Sort: ID</option><option value="title" ${f.sort==='title'?'selected':''}>Sort: title</option></select><button class="btn" data-action="export-filtered" data-type="${type}">${ic('download')}Export</button>${f.q||f.a||f.b?`<button class="btn ghost" data-action="clear-filter" data-type="${type}">Clear</button>`:''}</div>`;}
function pinButton(type,id){const chosen=!!review.entries[keyOf(type,id)];return `<button class="pin ${chosen?'selected':''}" data-action="pin" data-type="${type}" data-id="${E(id)}" aria-label="${chosen?'Remove from':'Add to'} review: ${E(id)}" aria-pressed="${chosen}">${ic('pin')}</button>`;}
function columns(type){return {
 metrics:['Definition','Type / unit','Availability'],native:['Family','Domain','Evidence boundary'],alarms:['Alarm / condition','Severity','Owner / persistence'],queries:['Question / query','Language','Validation'],sops:['Procedure','Owner','Applicability'],decisions:['Proposed decision','Scope','Implementation disposition'],opsGates:['Qualification gate','Status','Criterion'],gates:['Qualification gate','Recorded status','Evidence'],findings:['Finding','Priority','Owner'],alignment:['Clarification','Classification','Documentation status'],fields:['Field','Type','Meaning'],api:['HTTP operation','Method','Path'],sources:['Source','Kind','Reviewed']
 }[type]||['Record','Scope','Status'];}
function rowCells(type,r){let sub='',middle='',last='';switch(type){
 case 'metrics':sub=r.definition;middle=`${pill(r.type)}<div class="secondary">${E(r.unit)}</div>`;last=statusPill(r.availability);break;
 case 'native':sub=r.purpose;middle=E(r.domain);last=E(r.status);break;
 case 'alarms':sub=r.meaning;middle=pill(r.severity,r.severity==='critical'?'red':'amber');last=E(r.owner)+`<div class="secondary">For ${E(r.for)} · ${E(r.sop)}</div>`;break;
 case 'queries':sub=r.interpretation;middle=pill(r.language,'blue');last=E(r.validation || r.status);break;
 case 'sops':sub=r.trigger;middle=E(r.owner);last=E(r.applicability);break;
 case 'decisions':sub=r.id.startsWith('AP-')?r.group:'';middle=pill(r.scope,'blue');last=E(r.disposition||'Proposed within its original evaluation. No acceptance is implied.');break;
 case 'opsGates':middle=statusPill(r.status);last=E(r.criterion);break;
 case 'gates':middle=statusPill(r.status.replaceAll('_',' '));last=E(r.evidence);break;
 case 'findings':sub=r.risk;middle=pill(r.priority,'amber');last=E(r.owner);break;
 case 'alignment':sub=r.issue;middle=E(r.classification);last=E(r.documentation_status);break;
 case 'fields':sub=r.description||'';middle=pill(valueText(r.type|| (r.enum?'enum':r.const!==undefined?'constant':'specified')));last=E(r.description|| (r.enum?'Allowed: '+r.enum.join(', '):r.const!==undefined?'Fixed value: '+r.const:'See schema constraints.'));break;
 case 'api':middle=pill(r.method,r.method==='GET'?'blue':'amber');last=`<code>${E(r.path)}</code>`;break;
 case 'sources':sub=r.purpose;middle=E(r.kind);last=E(r.reviewed_on);break;
 }
 return `<td class="title-cell">${openButton(type,r.id,title(r),'title-btn')}${sub?`<span class="secondary">${E(sub.length>190?sub.slice(0,190)+'…':sub)}</span>`:''}</td><td>${middle}</td><td>${last}</td>`;
}
function pagination(type,n){const f=filters[type]||{};const pages=Math.max(1,Math.ceil(n/PAGE));const page=Math.min(f.page||1,pages);return `<div class="pagination"><span aria-live="polite">${n?`${(page-1)*PAGE+1}–${Math.min(page*PAGE,n)} of ${n}`:'0'} records${n!==D[type].length?` · filtered from ${D[type].length}`:''}</span><div class="actions"><button class="btn small" data-action="page" data-type="${type}" data-page="${page-1}" ${page===1?'disabled':''}>Previous</button><span>Page ${page} / ${pages}</span><button class="btn small" data-action="page" data-type="${type}" data-page="${page+1}" ${page===pages?'disabled':''}>Next</button></div></div>`;}
function renderCollection(type){const c=cfg[type];const a=getFiltered(type),page=Math.min(filters[type]?.page||1,Math.max(1,Math.ceil(a.length/PAGE)));const show=a.slice((page-1)*PAGE,page*PAGE);return head(meta[type].parent==='evidence'?'Review & qualification':'Operating reference',c.title,c.subtitle)+tabs(meta[type].parent)+pageNotice(type)+(type==='fields'?renderLogExamples():'')+toolbar(type)+(show.length?`<div class="table-wrap"><table><thead><tr><th>ID</th>${columns(type).map(t=>`<th>${E(t)}</th>`).join('')}<th><span class="sr-only">Review bookmark</span></th></tr></thead><tbody>${show.map(r=>`<tr><td class="id">${E(r.id)}</td>${rowCells(type,r)}<td class="action-col">${pinButton(type,r.id)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${ic('search')}<h3>No matching records</h3><p>Try a different phrase or clear the filters. The underlying catalog is unchanged.</p><button class="btn" data-action="clear-filter" data-type="${type}">Clear filters</button></div>`)+pagination(type,a.length);}
function renderLogExamples(){return `<div class="grid equal"><section class="panel"><div class="panel-head"><div><h2>Actual R14 access shape</h2><p>Six emitted fields · the values below are a synthetic fixture</p></div>${pill('Implemented shape','green')}</div><div class="panel-body">${codeBlock('C2 access example',JSON.stringify(D.accessExample,null,2))}<p class="small muted">No native source timestamp or durable-request trace binding is established by this access record.</p>${sourceLink('operations/schemas/r14-access.schema.json','Read access schema')}</div></section><section class="panel"><div class="panel-head"><div><h2>Normalized event envelope</h2><p>40 field definitions · proposed, not installed in R14</p></div>${pill('Proposed','amber')}</div><div class="panel-body"><p class="small muted">Separate source time from observation time, explicit synthetic execution from real workloads, and unknown amounts from zero.</p><details style="margin-top:15px"><summary style="cursor:pointer;font-size:12px">Inspect a synthetic normalized example</summary>${codeBlock('Proposed fixture, not live telemetry',JSON.stringify(D.eventExample,null,2))}</details><div class="actions" style="margin-top:15px">${sourceLink('operations/schemas/operational-event.schema.json','Read event schema')}</div></div></section></div>`;}
function renderBlueprints(){return head('Operating experience','Twelve views to qualify, not pretend to run.','These are dashboard specifications retained from the operational review. The data pipelines and access policies are not implemented here.')+tabs('metrics')+note('This review application <strong>showcases the specifications</strong>. It is not a live implementation of these operational dashboards.')+`<div class="grid three">${D.blueprints.map(r=>`<section class="panel blueprint">${pill(r.id)}<h3>${E(r.title)}</h3><p>${E(r.decision)}</p><ul>${r.panels.slice(0,4).map(p=>`<li>${E(p)}</li>`).join('')}</ul><div class="actions">${openButton('blueprints',r.id,'Review specification','btn small')}${pinButton('blueprints',r.id)}</div></section>`).join('')}</div>`;}
function renderEvidence(){return head('Versioned proof','Evidence is scoped. Acceptance is separate.','Inspect the recorded result, what was exercised, and what remains unproved. Counts are never added across overlapping releases.')+tabs('evidence')+note('Everything on this page is <strong>retained evidence from the C2 snapshot</strong>. No application tests, CI status or production systems are refreshed by opening this dashboard.','blue')+
 `<div class="grid three">${D.evidence.map(r=>`<section class="panel evidence-card">${pill(r.scope,'blue')}<h3 style="margin-top:13px">${E(r.title)}</h3><div class="receipt-value">${E(r.value)}</div><div class="small muted">${E(r.unit)}</div><p>${E(r.supports)}</p><p class="limit">Not established: ${E(r.limits)}</p><div class="actions">${openButton('evidence',r.id,'Inspect receipt','btn small')}${pinButton('evidence',r.id)}</div></section>`).join('')}</div>`+
 `<section class="panel section-gap"><div class="panel-head"><div><h2>One promotion roadmap</h2><p>Progression requires accepted evidence, not more screens.</p></div>${pill('No production approval','amber')}</div>${D.roadmap.map(r=>`<div class="timeline-item"><span class="phase">${E(r.phase.split(':')[0])}</span><div><h3>${E(r.phase.split(': ').slice(1).join(': '))}</h3><p>${E(r.work)}</p><div class="criteria"><strong>Required evidence</strong> · ${E(r.evidence)}</div></div>${pill(r.status,'amber')}</div>`).join('')}</section>`;
}
function filteredDocs(){const f=filters.documents||{};return D.documents.filter(d=>(!f.q||JSON.stringify(d).toLowerCase().includes(f.q.toLowerCase()))&&(!f.group||d.group===f.group)&&(!f.mode||f.mode==='all'||(f.mode==='featured'?d.featured:f.mode==='apps'?d.application:true))).sort((a,b)=>Number(b.featured)-Number(a.featured)||a.title.localeCompare(b.title));}
function renderDocuments(){const f=filters.documents||{mode:'featured'},a=filteredDocs();return head('Knowledge library','The full work, with provenance.','Open a document, inspect its scope and source hash, or add it to the review agenda.')+note('All record text is embedded in this dashboard. <strong>Full-document links require the complete package</strong>, with the adjacent documentation directory retained.')+
 `<div class="toolbar"><label class="search-field" for="catalogSearch">${ic('search')}<span class="sr-only">Find documents</span><input type="search" id="catalogSearch" placeholder="Find a document, release or topic…" value="${E(f.q||'')}" data-filter="q" data-type="documents"></label><select data-filter="group" data-type="documents" aria-label="Document family"><option value="">All families</option>${[...new Set(D.documents.map(d=>d.group))].sort().map(g=>`<option ${f.group===g?'selected':''}>${E(g)}</option>`).join('')}</select><div class="segmented" aria-label="Document selection">${[['featured','Key documents'],['all','All'],['apps','Applications']].map(([m,l])=>`<button class="${(f.mode||'featured')===m?'active':''}" data-action="doc-mode" data-mode="${m}">${l}</button>`).join('')}</div></div><p class="small muted" aria-live="polite" style="margin:0 0 14px">${a.length} matching artifacts · 47 indexed HTML artifacts in this review</p><div class="doc-grid">${a.map(r=>`<article class="doc-card"><div class="actions">${ic(r.application?'grid':'file')}${pill(r.group)}${r.application?pill('Separate application','blue'):''}</div><h3>${E(r.title)}</h3><p>${E(r.intro||r.status)}</p><span class="small muted">${E(r.status)}</span><div class="actions">${openButton('documents',r.id,'Inspect','btn small')}${sourceLink(r.path,r.application?'Open artifact':'Read document','btn small')}${pinButton('documents',r.id)}</div></article>`).join('')}</div>${a.length?'':`<div class="empty">${ic('folder')}<h3>No matching documents</h3><p>Try all documents or clear the search and family filters.</p><button class="btn" data-action="clear-filter" data-type="documents">Clear filters</button></div>`}`;}
function renderReview(){const selected=Object.entries(review.entries);const counts=s=>selected.filter(([k,r])=>r.status===s);return head('Private review workspace','Make the next review decisive.','Collect the records that matter, annotate questions, and export a portable meeting packet.',`<button class="btn" data-action="import-review">${ic('download')}Import</button><button class="btn" data-action="export-review">${ic('download')}Export JSON</button><button class="btn primary" data-action="meeting-pack">${ic('file')}Meeting brief</button>`)+
 `<div class="review-guard"><strong>Annotations only.</strong> “Reviewed” records your local review. It never accepts an ADR, closes a gate, resolves an incident or changes the source material. Owner names here are unverified text.</div>`+
 `<div class="review-tools"><label for="reviewerName">Reviewer / meeting label <input id="reviewerName" type="text" maxlength="120" value="${E(review.reviewer)}" placeholder="Optional — local, unverified" style="min-width:240px"><button class="btn small" data-action="save-reviewer">Save label</button></label><div class="storage-line"><label class="switch"><input id="persistReview" type="checkbox" ${persistent?'checked':''}>Save annotations in this browser</label><span>${persistent?'Unencrypted local storage':'Memory only · export before closing'}</span><span>${selected.length} selected · ${counts('Reviewed').length} locally reviewed</span></div>${storageConflict?note('Saved data changed in another tab. Writes are paused until you reload. Export your in-memory review before replacing it. <button class="btn small" data-action="reload-review">Reload saved review</button>','amber'):''}${invalidSaved?note('Existing saved data could not be validated and has not been overwritten. <button class="btn small" data-action="export-invalid">Export raw recovery copy</button> <button class="btn small danger" data-action="clear-invalid">Discard invalid saved copy</button>','amber'):''}<div class="actions"><button class="btn small" data-action="suggested">Add suggested review topics</button><button class="btn small" data-action="print-review">${ic('print')}Print review</button><button class="btn small danger" data-action="reset-review">Reset this review</button></div></div>`+
 (selected.length?`<div class="board">${['Unreviewed','Follow-up','Reviewed'].map(status=>`<section class="board-col"><div class="board-head"><span>${status==='Unreviewed'?'To review':status==='Reviewed'?'Reviewed locally':'Follow-up'}</span>${pill(counts(status).length)}</div>${counts(status).sort(([ka,a],[kb,b])=>['High','Normal','Low'].indexOf(a.priority)-['High','Normal','Low'].indexOf(b.priority)).map(([key,a])=>{const {type,r}=records.get(key);return `<article class="board-card"><div class="eyebrow">${E(meta[type].label)} · ${E(r.id)}</div><h3>${E(title(r))}</h3><p>${E(a.note||'No review note yet.')}</p><div class="actions">${pill(a.priority,a.priority==='High'?'amber':'')}${a.owner?pill(a.owner):''}</div><div class="actions">${openButton(type,r.id,'Review record','btn small')}${pinButton(type,r.id)}</div></article>`;}).join('')||'<p class="small muted">No records in this column.</p>'}</section>`).join('')}</div>`:`<div class="empty">${ic('board')}<h3>Your review starts with a record.</h3><p>Bookmark a decision, alarm, gate or procedure. Add questions and follow-up owners without changing its source status.</p><button class="btn primary" data-action="suggested">Add suggested topics</button></div>`);
}
function render(preserve=false){const focus=preserve?document.activeElement:null,focusId=focus?.id,start=focus?.selectionStart,end=focus?.selectionEnd;updateNav();let html='';if(view==='overview')html=renderOverview();else if(view==='architecture')html=renderArchitecture();else if(view==='comparison')html=renderComparison();else if(view==='blueprints')html=renderBlueprints();else if(view==='evidence')html=renderEvidence();else if(view==='documents')html=renderDocuments();else if(view==='review')html=renderReview();else if(view==='scenarios')html=renderOverview();else if(cfg[view])html=renderCollection(view);else html=renderOverview();$('main').innerHTML=html+foot();if(preserve&&focusId&&$(focusId)){try{$(focusId).focus({preventScroll:true});if(start!==null&&start!==undefined)$(focusId).setSelectionRange(start,end);}catch(e){}}renderTour();}
function detailSection(heading,text){if(text===undefined||text===null||text==='')return '';return `<section class="detail-section"><h3>${E(heading)}</h3>${Array.isArray(text)?`<ol>${text.map(x=>`<li>${E(x)}</li>`).join('')}</ol>`:`<p>${E(text)}</p>`}</section>`;}
function kv(label,value){return `<div class="kv"><dt>${E(label)}</dt><dd>${E(valueText(value))}</dd></div>`;}
function codeBlock(label,text){return `<div class="code-head"><span>${E(label)}</span><button class="btn small" data-action="copy-text" data-copy="${E(text)}">${ic('copy')}Copy</button></div><pre><code>${E(text)}</code></pre>`;}
function related(type,ids){const good=[...new Set(ids||[])].filter(id=>records.has(keyOf(type,id)));return good.length?`<div class="related">${good.map(id=>openButton(type,id,id,'related-btn')).join('')}</div>`:'';}
function relationSection(label,type,ids){const html=related(type,ids);return html?`<section class="detail-section"><h3>${E(label)}</h3>${html}</section>`:'';}
function sourcesFor(r){return String(r.source||r.evidence||'').split(',').map(x=>x.trim()).filter(x=>records.has(keyOf('sources',x)));}
function detailPath(type,r){return {metrics:'Aperture-Operational-Review.html#metrics',native:'Aperture-Operational-Review.html#litellm',alarms:'Aperture-Operational-Review.html#alarms',queries:'Aperture-Operational-Review.html#queries',sops:'Aperture-Operational-Review.html#sops',fields:'Aperture-Operational-Review.html#log-structure',opsGates:'Aperture-Operational-Review.html#qualification',gates:'Aperture-Consolidated-Documentation.html#roadmap',findings:'Aperture-Operational-Review.html#findings',alignment:'Alignment-Register.html',blueprints:'Aperture-Operational-Review.html#dashboards',decisions:'Decision-Register.html#'+r.id,api:'Aperture-Consolidated-Documentation.html#contracts',sources:r.path_or_url,evidence:r.path,documents:r.path,scenarios:'Aperture-Consolidated-Documentation.html'}[type];}
function detailBody(type,r){let html='';switch(type){
 case 'metrics':{
  const alarms=D.alarms.filter(a=>a.expression.includes(r.name)).map(a=>a.id);const queries=D.queries.filter(q=>q.query.includes(r.name)).map(q=>q.id);
  html=`${pill(r.availability,'amber')}<dl class="detail-grid">${kv('Type / unit',r.type+' / '+r.unit)}${kv('Domain',r.domain)}${kv('Owner',r.owner)}${kv('Labels',r.labels)}</dl>`+detailSection('Definition',r.definition)+detailSection('Collection',r.collection)+detailSection('Missing evidence',r.missing_semantics)+detailSection('Reset semantics',r.reset_semantics)+detailSection('Scope contract',r.scope_contract)+detailSection('Cardinality and privacy',r.cardinality)+detailSection('Label contract',r.label_contract)+detailSection('Required verification',r.verification)+relationSection('Alarm references','alarms',[...r.alarms,...alarms])+relationSection('Query references','queries',[...r.queries,...queries]);break;}
 case 'native':html=note(E(r.status),'blue')+`<dl class="detail-grid">${kv('Declared kind',r.documented_kind)}${kv('Unit',r.unit)}${kv('Domain',r.domain)}</dl>`+detailSection('Purpose',r.purpose)+detailSection('Qualification required',r.qualification);break;
 case 'alarms':html=`${pill(r.status,'amber')}<dl class="detail-grid">${kv('Design severity',r.severity)}${kv('Owner',r.owner)}${kv('Persistence',r.for)}${kv('Maintenance inhibition',r.maintenance_inhibition)}</dl>`+detailSection('Meaning',r.meaning)+codeBlock('Proposed PromQL condition',r.expression)+detailSection('Dependencies',r.dependencies)+detailSection('Data quality requirement',r.data_quality_requirement)+detailSection('Recovery and closure',r.recovery)+relationSection('Response procedure','sops',[r.sop])+relationSection('Triage queries','queries',r.triage_queries)+relationSection('Referenced canonical metrics','metrics',D.metrics.filter(m=>r.expression.includes(m.name)).map(m=>m.id));break;
 case 'queries':html=`<div class="actions">${pill(r.language,'blue')}${pill(r.scope+' scope')}</div>`+detailSection('Validation boundary',r.validation||r.status)+codeBlock(r.language+' recipe · copy only',r.query)+detailSection('Interpretation',r.interpretation)+detailSection('Required parameters',r.parameters.length?r.parameters:['No bound parameters specified.'])+ (r.parameters.length?`<section class="detail-section"><h3>Prepare bindings · not execution</h3><p>These fields produce a separate binding object. The query remains unchanged. Use only an authorized environment.</p><div class="detail-grid">${r.parameters.map(p=>`<label class="small muted">${E(p)}<input class="field" data-binding="${E(p)}" type="text" placeholder="${p==='now'?'Unix timestamp, supplied by operator':'Explicit '+E(p)}" style="width:100%;margin-top:5px" maxlength="180"></label>`).join('')}</div><button class="btn small" data-action="copy-bindings">${ic('copy')}Copy binding object</button></section>`:'')+relationSection('Procedures using this query','sops',D.sops.filter(s=>(s.queries||[]).includes(r.id)).map(s=>s.id))+relationSection('Alarm references','alarms',D.alarms.filter(a=>(a.triage_queries||[]).includes(r.id)).map(a=>a.id));break;
 case 'sops':html=`<dl class="detail-grid">${kv('Accountable role',r.owner)}${kv('Applicability',r.applicability)}</dl>`+detailSection('Trigger',r.trigger)+detailSection('Prerequisites',r.preconditions)+detailSection('Diagnosis',r.diagnose)+detailSection('Containment',r.containment)+`<section class="detail-section"><h3>Procedure · rehearsal checklist</h3><p>Local review aid only. Checking a step does not execute or certify it. Save the review note to retain checks.</p>${r.procedure.map((step,i)=>`<label class="check-item"><input type="checkbox" data-sop-step="${i}" ${annotation(keyOf(type,r.id)).checks.includes(i)?'checked':''}><span>${E(step)}</span></label>`).join('')}</section>`+detailSection('Verification',r.verification)+detailSection('Rollback / abort',r.rollback)+detailSection('Escalation',r.escalation)+(r.commands?codeBlock('Source-aligned commands · not executed here',r.commands):'')+relationSection('Diagnostic queries','queries',r.queries)+detailSection('Evidence to retain',r.evidence)+detailSection('Closure',r.closure)+detailSection('Review cadence',r.review);break;
 case 'decisions':html=`<div class="actions">${pill(r.scope,'blue')}${pill(r.status,'amber')}</div>`+note('<strong>Implementation disposition</strong><br>'+E(r.disposition||'Retained as a proposal in its original evaluation. No acceptance is implied.'),r.disposition?.includes('RECONSIDER')?'amber':'')+`<div class="adr-content">${r.body}</div>`+relationSection('Cross-scope decisions','decisions',r.related)+`<div class="source-note">Original decision-text SHA-256<br><code>${E(r.original_text_sha256)}</code></div>`;break;
 case 'opsGates':html=pill(r.status,'amber')+detailSection('Acceptance criterion',r.criterion)+note('There is no closure control here. A local review note is not production qualification evidence.','amber');break;
 case 'gates':html=statusPill(r.status.replaceAll('_',' '))+detailSection('Retained evidence / remaining work',r.evidence)+detailSection('Scope',r.scope)+note('Status belongs to the recorded candidate snapshot. It is not a fresh CI or deployment observation.');break;
 case 'findings':html=pill(r.priority,'amber')+detailSection('Risk',r.risk)+detailSection('Recommendation',r.recommendation)+detailSection('Responsible role',r.owner)+detailSection('Acceptance evidence',r.acceptance)+detailSection('Source state',r.state);break;
 case 'alignment':html=`${pill(r.documentation_status,'blue')}<dl class="detail-grid">${kv('Area',r.area)}${kv('Classification',r.classification)}</dl>`+detailSection('Issue',r.issue)+detailSection('Aligned statement',r.consolidated_resolution)+detailSection('Remaining boundary',r.remaining_boundary)+detailSection('Runtime change',r.runtime_change?'Source says runtime change recorded.':'No runtime change. Documentation clarification only.')+sourceLink(r.evidence,'Inspect alignment evidence');break;
 case 'fields':html=note('Proposed normalization schema, not native OTLP JSON or automatically emitted R14 fields.')+detailSection('Field meaning',r.description||'Inspect the allowed values and validation constraints below.')+codeBlock('Field constraints',JSON.stringify(Object.fromEntries(Object.entries(r).filter(([k])=>!['id','title'].includes(k))),null,2));break;
 case 'api':html=`<dl class="detail-grid">${kv('Method',r.method)}${kv('Operation ID',r.operationId)}</dl>`+codeBlock('Implemented route',r.method+' '+r.path)+note('Documentation only. The review dashboard has no API credentials and cannot invoke this operation.')+sourceLink('runtime/aperture-r14/Aperture-Server-Release14.openapi.json','Open complete OpenAPI');break;
 case 'blueprints':html=pill(r.status,'amber')+detailSection('Audience',r.audience)+detailSection('Decision supported',r.decision)+detailSection('Proposed panels',r.panels)+detailSection('Access boundary',r.access)+relationSection('Drill-down recipes','queries',r.drill_down);break;
 case 'evidence':html=`${pill(r.scope,'blue')}<div class="stat-value" style="margin:18px 0 6px">${E(r.value)}</div><p class="muted small">${E(r.unit)}</p>`+detailSection('What the receipt supports',r.supports)+detailSection('What is not established',r.limits)+detailSection('Snapshot date',r.date)+codeBlock('Receipt SHA-256',r.sha256)+note('Historical receipt. This dashboard did not execute the suite; counts overlap across releases and must not be summed.');break;
 case 'documents':html=`<div class="actions">${pill(r.group,'blue')}${pill(r.status)}</div>`+detailSection('Document introduction',r.intro)+detailSection('Content map',r.headings)+`<dl class="detail-grid">${kv('Artifact',r.file)}${kv('Size',new Intl.NumberFormat().format(r.bytes)+' bytes')}</dl>`+codeBlock('Reader / artifact SHA-256',r.sha256)+note(r.application?'This is a separate application artifact. Opening its HTML runs its documented mode, not a live backend.':'Full-document links use the packaged documentation directory. The preview remains available standalone.');break;
 case 'sources':html=`<dl class="detail-grid">${kv('Kind',r.kind)}${kv('Reviewed on',r.reviewed_on)}</dl>`+detailSection('Purpose',r.purpose)+detailSection('Source path / URL',r.path_or_url)+(r.sha256?codeBlock('Preserved-source SHA-256',r.sha256):'')+note('Recorded source review, not continuous verification. External links are opened only on explicit action.');break;
 case 'scenarios':html=detailSection('Review question',r.question)+note('A guided evidence path. No synthetic incident is created, no query runs, and no monitoring state changes.','blue')+`<div class="scenario-steps">${r.steps.map(([t,id,label],i)=>`<button class="scenario-step" data-action="open" data-type="${t}" data-id="${id}"><div class="stepno">STEP 0${i+1} · ${id}</div><h3>${E(label)}</h3><p>${E(title(records.get(keyOf(t,id)).r))}</p></button>`).join('')}</div>`;break;
 }
 return html+relationSection('Supporting operational sources','sources',sourcesFor(r));
}
function renderDetail(type,id){const item=records.get(keyOf(type,id));if(!item)return;activeRecord={type,id};const r=item.r,a=annotation(keyOf(type,id));const selected=!!review.entries[keyOf(type,id)];const isScenario=type==='scenarios';dirty=false;
 $('detail').innerHTML=`<div class="drawer-shell"><header class="drawer-head"><div><div class="eyebrow">${E(meta[type].label)} · ${E(id)}</div><h2 id="detailTitle">${E(title(r))}</h2></div><button class="icon-btn" data-action="close-detail" aria-label="Close record">${ic('close')}</button></header><div class="drawer-body">${detailTrail.length>0?`<button class="btn small ghost" data-action="back-detail">${ic('back')}Previous record</button>`:''}${detailBody(type,r)}${!isScenario?`<form class="note-form" id="noteForm"><h3>Local review annotation</h3><p class="small muted">Changes only your review board. Source status remains unchanged.</p><div class="two-fields"><div><label for="reviewStatus">Review disposition</label><select id="reviewStatus">${['Unreviewed','Follow-up','Reviewed'].map(s=>`<option ${s===a.status?'selected':''}>${s}</option>`).join('')}</select></div><div><label for="reviewPriority">Priority</label><select id="reviewPriority">${['Normal','High','Low'].map(s=>`<option ${s===a.priority?'selected':''}>${s}</option>`).join('')}</select></div></div><label for="followOwner">Follow-up owner · unverified label</label><input id="followOwner" type="text" maxlength="120" value="${E(a.owner)}" placeholder="Optional owner or team"><label for="reviewNote">Question, observation or next action</label><textarea id="reviewNote" maxlength="6000" placeholder="Record your review, not credentials, prompts or confidential incident details.">${E(a.note)}</textarea><span id="draftState" class="small muted" aria-live="polite">${a.updated_at?'Saved '+E(new Date(a.updated_at).toLocaleString()):'No annotation saved.'}</span></form>`:''}</div><footer class="drawer-actions">${isScenario?'':`<button class="btn primary" data-action="save-note">${ic('check')}Save review</button><button class="btn" data-action="pin" data-type="${type}" data-id="${E(id)}">${ic('pin')}${selected?'Remove from board':'Add to board'}</button>`}${sourceLink(detailPath(type,r),isScenario?'Read handbook':'Source document')}<button class="btn small ghost" data-action="copy-link">${ic('link')}Copy link</button></footer></div>`;
 if(!$('detail').open){lastFocus=document.activeElement;$('detail').showModal();}else $('detail').querySelector('.drawer-body').scrollTop=0;
}
function markDirty(){if(!$('detail').open)return;dirty=true;if($('draftState'))$('draftState').textContent='Unsaved review changes.';}
function mayLeave(){return !dirty || confirm('Discard unsaved review annotations? The source record is unchanged.');}
function navigate(route){if(!mayLeave())return;dirty=false;skipRouteGuard=true;location.hash=route;closeMenu();if(location.hash.slice(1)===lastRoute)routeChanged();}
function openRecord(type,id){if(!records.has(keyOf(type,id))){toast('That record is not present in this snapshot.');return;}if(!mayLeave())return;if(activeRecord)detailTrail.push({...activeRecord});else detailTrail=[];dirty=false;skipRouteGuard=true;location.hash=type+'/'+encodeURIComponent(id);if(location.hash.slice(1)===lastRoute)routeChanged();}
function closeDetail(){if(!mayLeave())return;dirty=false;activeRecord=null;detailTrail=[];$('detail').close();navigate(view);if(lastFocus&&document.contains(lastFocus))lastFocus.focus({preventScroll:true});}
function routeChanged(){const raw=location.hash.slice(1)||'overview';if(!skipRouteGuard&&!mayLeave()){skipRouteGuard=true;location.hash=lastRoute;return;}skipRouteGuard=false;dirty=false;const [v,encoded]=raw.split('/');view=meta[v]?v:'overview';let id=null;try{id=encoded?decodeURIComponent(encoded):null;}catch(error){toast('Malformed record link. Showing the catalog instead.');}lastRoute=raw;if(!filters.documents)filters.documents={mode:'featured',q:'',group:''};render();if(id&&records.has(keyOf(view,id)))renderDetail(view,id);else{if($('detail').open)$('detail').close();activeRecord=null;detailTrail=[];if(id)toast('Record not found in this snapshot. The catalog is still available.');window.scrollTo(0,0);}closeMenu();}
function download(filename,text,mime='application/json'){const blob=new Blob([text],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied.');}catch(e){const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';const host=$('detail').open?$('detail'):$('command').open?$('command'):document.body;host.append(ta);ta.select();let ok=false;try{ok=document.execCommand('copy');}catch(e){}ta.remove();if(ok)toast('Copied.');else{download('aperture-copy.txt',text,'text/plain');toast('Clipboard unavailable. A text file was exported instead.');}}}
function exportReview(){download('Aperture-Review-Notes.json',JSON.stringify(review,null,2));toast('Review annotations exported. Source records were not modified.');}
function reviewBrief(){const sections=[`# Aperture review brief\n\nSource snapshot: C2, 21 October 2026\nDashboard: D1\nBaseline fingerprint: ${D.fingerprint}\nMeeting / reviewer label (unverified): ${review.reviewer||'Not specified'}\nExported: ${new Date().toISOString()}\n\nLOCAL ANNOTATIONS ONLY. No ADR acceptance, qualification closure, runtime change or production approval. Evidence counts are version-bound, not cumulative.\n`];Object.entries(review.entries).forEach(([key,a])=>{const {type,r}=records.get(key);sections.push(`## ${r.id}: ${title(r)}\n\nRegister: ${meta[type].label}\nLocal review: ${a.status}\nPriority: ${a.priority}\nFollow-up owner (unverified): ${a.owner||'Unassigned'}\nSource status: ${r.status||r.availability||r.documentation_status||r.state||'See source record'}\n\n${a.note||'No review note recorded.'}\n\nSource: documentation/${detailPath(type,r)}\n${a.checks.length?'Rehearsal checklist marks (not execution evidence): '+a.checks.map(i=>i+1).join(', ')+'\n':''}`);});sections.push('## Remaining platform boundary\n\nR14 is a single-node reference with synthetic inference. The LiteLLM adapter is not integrated. Production telemetry, enterprise qualification and production acceptance remain open.');return sections.join('\n');}
function renderPrint(){let html=`<h1>Aperture review brief</h1><p>C2 source snapshot · 21 October 2026 · ${E(review.reviewer||'Unassigned review')}</p><p><strong>Local annotations only. No authority, acceptance or live operational state.</strong></p>`;for(const [key,a] of Object.entries(review.entries)){const {type,r}=records.get(key);html+=`<section class="print-record"><h2>${E(r.id)} · ${E(title(r))}</h2><p>${E(meta[type].label)} · Local disposition: ${E(a.status)} · Priority: ${E(a.priority)}</p><p>Owner (unverified): ${E(a.owner||'Unassigned')}</p><p>${E(a.note||'No note recorded.')}</p><p>Source: documentation/${E(detailPath(type,r))}</p></section>`;}$('printArea').innerHTML=html;}
function startSearch(){if(!$('command').open)$('command').showModal();$('globalSearch').value='';searchFocus=0;renderSearch('');setTimeout(()=>$('globalSearch').focus(),30);}
function renderSearch(query){const q=query.trim().toLowerCase();const matches=q?searchIndex.filter(x=>x.search.includes(q)).sort((a,b)=>Number(b.short.includes(q))-Number(a.short.includes(q))):searchIndex.filter(x=>['AP-ADR-004','AL-01','SOP-09','SQL-04','OG-01','DOC-OPS'].includes(x.r.id)).slice(0,12);searchResults=matches.slice(0,45);searchFocus=Math.min(searchFocus,Math.max(0,searchResults.length-1));$('searchResults').innerHTML=searchResults.length?searchResults.map(({type,r},i)=>`<button class="command-item ${i===searchFocus?'focused':''}" data-action="search-result" data-index="${i}"><span class="type">${E(meta[type].label)}</span><span><h3>${E(title(r))}</h3><p>${E(r.id)} · ${E(String(r.status||r.domain||r.scope||r.applicability||'C2 snapshot').slice(0,140))}</p></span></button>`).join(''):`<div class="empty"><h3>No matching records</h3><p>Search a source identifier such as SOP-09, or a topic such as uncertainty.</p></div>`;$('searchSummary').textContent=q?`${matches.length} matches · showing ${searchResults.length}. ↑ ↓ to navigate, Enter to inspect, Escape to close.`:'Suggested starting points · search full record text across all embedded catalogs.';}
function openAbout(){const repo=D.baseline.repository;$('aboutContent').innerHTML=`<div class="eyebrow muted">Sources & scope</div><h2 id="aboutTitle" style="margin-top:10px">A faithful snapshot, not a live control room.</h2><p>This review dashboard is derived from Documentation Baseline C2, dated 21 October 2026. Original documents and decision text are preserved in the full package.</p><dl class="detail-grid">${kv('Persistent reference','R14 · SQLite schema 2 · DELETE journal')}${kv('Execution','Synthetic; no live provider integration')}${kv('Decision status','All 352 records remain Proposed')}${kv('Review storage',persistent?'Unencrypted browser local storage':'Memory only, until you opt in')}</dl><p>Repository status is a retained observation, not a fresh GitHub check: PR #1 was draft and unmerged, with zero observed check runs. Main ${E(repo.main.slice(0,12))}; correction ${E(repo.head.slice(0,12))}.</p><p>All dashboard searches and filtering run locally. Exporting a review does not submit it to anyone. Names entered as reviewers or owners are unverified labels. Do not enter credentials, raw prompts or confidential operational records.</p><p>Local storage is not an authentication boundary. Revision checks detect some stale writes but do not provide atomic multi-tab collaboration. Full-document links require the complete package; external source navigation is explicit.</p><p><strong>Dataset fingerprint</strong><br><code>${E(D.fingerprint)}</code></p><div class="actions" style="margin-top:20px"><button class="btn" data-action="export-provenance">${ic('download')}Export provenance</button>${sourceLink('Aperture-Consolidated-Documentation.html','Read the baseline')}</div>`;$('about').showModal();}
const tourSteps=[['overview','The work at a glance','Separate source coverage from operational readiness.'],['architecture','The operating boundary','Inspect current reference, candidate and enterprise target.'],['metrics','The measurement contract','Definitions are not live telemetry.'],['alarms','From signal to safe action','Inspect AL-01 and its linked recovery SOP.'],['sops','Operational procedure','Review a complete procedure and its evidence boundary.'],['evidence','Qualification before claims','See the receipts and unclosed promotion gates.'],['review','Prepare a focused review','Collect questions and export the meeting brief.']];
function renderTour(){if(tour<0){$('tourBar').hidden=true;return;}const s=tourSteps[tour];$('tourBar').hidden=false;$('tourBar').innerHTML=`${pill(`${tour+1} / ${tourSteps.length}`,'green')}<strong>${E(s[1])}</strong><span class="tour-desc muted">${E(s[2])}</span><div class="actions"><button class="btn small" data-action="tour-prev" ${tour===0?'disabled':''}>Back</button><button class="btn small primary" data-action="tour-next">${tour===tourSteps.length-1?'Finish':'Next'}</button><button class="btn small ghost" data-action="tour-end" aria-label="End guided showcase">${ic('close')}</button></div>`;}
function closeMenu(){$('sidebar').classList.remove('open');$('overlay').classList.remove('visible');$('menuButton').setAttribute('aria-expanded','false');}
function eventAction(event){const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,t=el.dataset.type,id=el.dataset.id;
 switch(action){
 case 'navigate':navigate(el.dataset.route);break;
 case 'open':openRecord(t,id);break;
 case 'pin':if(dirty&&!mayLeave())return;dirty=false;pin(t,id);break;
 case 'about':openAbout();break;
 case 'close-about':$('about').close();break;
 case 'close-search':$('command').close();break;
 case 'close-detail':closeDetail();break;
 case 'back-detail':{if(!mayLeave())return;const old=detailTrail.pop();if(old){dirty=false;skipRouteGuard=true;location.hash=old.type+'/'+encodeURIComponent(old.id);}break;}
 case 'filter-domain':filters.metrics={q:'',a:el.dataset.domain,b:'',page:1,sort:'id'};navigate('metrics');break;
 case 'clear-filter':filters[t]=t==='documents'?{q:'',group:'',mode:'all'}:{q:'',a:'',b:'',sort:'id',page:1};render();break;
 case 'page':filters[t]={...(filters[t]||{}),page:Number(el.dataset.page)};render();break;
 case 'doc-mode':filters.documents={...(filters.documents||{}),mode:el.dataset.mode};render();break;
 case 'export-filtered':download('Aperture-'+t+'-filtered.json',JSON.stringify({snapshot:D.snapshot,baseline:D.fingerprint,register:t,filters:filters[t]||{},count:getFiltered(t).length,records:getFiltered(t)},null,2));toast('Filtered source records exported. No query or control was executed.');break;
 case 'copy-text':copy(el.dataset.copy);break;
 case 'copy-bindings':{const inputs=[...$('detail').querySelectorAll('[data-binding]')];if(inputs.some(i=>!i.value.trim())){toast('Provide every required parameter before copying.');return;}const pairs=inputs.map(i=>[i.dataset.binding,i.dataset.binding==='now'?Number(i.value):i.value]);if(pairs.some(([k,v])=>k==='now'&&(!Number.isFinite(v)||v<0))){toast('The supplied Unix timestamp must be a finite non-negative number.');return;}copy(JSON.stringify(Object.fromEntries(pairs),null,2));break;}
 case 'copy-link':copy(location.href);break;
 case 'save-note':{if(!activeRecord)return;const key=keyOf(activeRecord.type,activeRecord.id);const val={status:$('reviewStatus').value,priority:$('reviewPriority').value,owner:$('followOwner').value,note:$('reviewNote').value,checks:[...$('detail').querySelectorAll('[data-sop-step]:checked')].map(x=>Number(x.dataset.sopStep)),updated_at:new Date().toISOString()};if(val.note.length>6000||val.owner.length>120){toast('The annotation exceeds its length limit.');return;}if(mutateReview(next=>next.entries[key]=val)){dirty=false;const pinControl=$('detail').querySelector('.drawer-actions [data-action=pin]');if(pinControl)pinControl.innerHTML=ic('pin')+'Remove from board';$('draftState').textContent='Saved to your local review. Source status is unchanged.';toast('Review saved. No source decision or gate status changed.');render(true);}break;}
 case 'save-reviewer':{const label=$('reviewerName').value;if(label.length>120){toast('Keep the review label within 120 characters.');return;}if(mutateReview(n=>n.reviewer=label))toast('Review label saved locally.');break;}
 case 'suggested':if(mutateReview(n=>[['decisions','AP-ADR-004'],['findings','OF-01'],['opsGates','OG-09'],['gates','LQ-G04'],['sops','SOP-09']].forEach(([t,id])=>{const k=keyOf(t,id);if(!n.entries[k])n.entries[k]={...annotation(k)};}))){render();toast('Five review topics added; none marked reviewed.');}break;
 case 'export-review':exportReview();break;
 case 'meeting-pack':download('Aperture-Review-Brief.md',reviewBrief(),'text/markdown');toast('Meeting brief exported with scope and acceptance boundaries.');break;
 case 'print-review':renderPrint();document.body.classList.add('review-print');window.print();break;
 case 'import-review':$('importFile').click();break;
 case 'reset-review':if(confirm('Remove all annotations from this review workspace? Source records and exported copies are not changed.')){if(persistent){try{const current=localStorage.getItem(STORE);if((current?JSON.parse(current).revision:null)!==storageRevision){storageConflict=true;render();toast('Saved data changed. Reload before resetting.');return;}localStorage.removeItem(STORE);}catch(e){toast('Could not clear the saved review. Nothing was reset.');return;}}review=newReview();persistent=false;storageRevision=null;storageConflict=false;render();toast('Local review reset. Source records are unchanged.');}break;
 case 'reload-review':if(confirm('Replace the in-memory review with the saved copy? Export in-memory notes first to retain them.')){try{const raw=localStorage.getItem(STORE);review=raw?validateReview(JSON.parse(raw)):newReview();persistent=!!raw;storageRevision=review.revision;storageConflict=false;render();toast('Saved review reloaded.');}catch(e){toast('The saved review is invalid. Export an in-memory backup.');}}break;
 case 'export-invalid':download('Aperture-Review-Recovery.txt',invalidSaved||'','text/plain');break;
 case 'clear-invalid':if(confirm('Delete the invalid saved copy? Export it first for recovery.')){try{localStorage.removeItem(STORE);invalidSaved=null;storageRevision=null;render();}catch(e){toast('Storage could not be cleared.');}}break;
 case 'export-provenance':download('Aperture-Dashboard-Provenance.json',JSON.stringify({edition:'D1',snapshot:D.snapshot,fingerprint:D.fingerprint,sources:D.provenance,boundary:'Read-only C2 snapshot; local review annotations are not authority.'},null,2));break;
 case 'search-result':{const result=searchResults[Number(el.dataset.index)];if(result){$('command').close();openRecord(result.type,result.r.id);}break;}
 case 'start-tour':tour=0;navigate(tourSteps[0][0]);renderTour();break;
 case 'tour-prev':if(tour>0){tour--;navigate(tourSteps[tour][0]);}break;
 case 'tour-next':if(tour===tourSteps.length-1){tour=-1;renderTour();toast('Showcase complete. Review notes remain under your control.');}else{tour++;navigate(tourSteps[tour][0]);}break;
 case 'tour-end':tour=-1;renderTour();break;
 }
}
document.addEventListener('click',eventAction);
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&a.classList.contains('skip')){e.preventDefault();$('main').focus();return;}if(a){e.preventDefault();const route=a.getAttribute('href').slice(1);const parts=route.split('/');if(parts.length===2&&records.has(keyOf(parts[0],decodeURIComponent(parts[1]))))openRecord(parts[0],decodeURIComponent(parts[1]));else navigate(route);}});
let filterTimer;
document.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-filter]')){clearTimeout(filterTimer);const type=el.dataset.type,key=el.dataset.filter;filters[type]={...(filters[type]||{}),[key]:el.value,page:1};if(el.tagName==='INPUT')filterTimer=setTimeout(()=>render(true),130);}if(['reviewNote','followOwner'].includes(el.id))markDirty();});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-filter]')){clearTimeout(filterTimer);filters[el.dataset.type]={...(filters[el.dataset.type]||{}),[el.dataset.filter]:el.value,page:1};render(true);}if(['reviewStatus','reviewPriority'].includes(el.id)||el.matches('[data-sop-step]'))markDirty();if(el.id==='persistReview'){
 if(el.checked){if(invalidSaved){el.checked=false;toast('Resolve the preserved invalid copy before enabling saving.');return;}try{const existing=localStorage.getItem(STORE);if(existing&&JSON.parse(existing).revision!==storageRevision){storageConflict=true;el.checked=false;render();toast('Saved review differs. Reload before enabling writes.');return;}review={...review,updated_at:new Date().toISOString(),revision:revision()};localStorage.setItem(STORE,JSON.stringify(review));persistent=true;storageRevision=review.revision;toast('Saving enabled. Notes are stored unencrypted in this browser.');}catch(e){persistent=false;toast('Local storage unavailable. Export notes before closing.');}}
 else{if(!confirm('Disable saving and remove this workspace’s saved copy? In-memory notes and exported files remain.')){el.checked=true;return;}try{const current=localStorage.getItem(STORE);if((current?JSON.parse(current).revision:null)!==storageRevision){storageConflict=true;render();toast('Saved review changed. Reload before deleting it.');return;}localStorage.removeItem(STORE);persistent=false;storageRevision=null;toast('Saved copy removed. Notes remain in memory only.');}catch(e){toast('Could not remove the saved copy. Saving remains enabled.');}}
 render();}});
$('importFile').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5*1024*1024){toast('Import refused: maximum packet size is 5 MB.');return;}try{const incoming=validateReview(JSON.parse(await file.text()));if(!confirm(`Replace this review with ${Object.keys(incoming.entries).length} imported annotations? This is not a merge. Source records are unchanged.`))return;if(mutateReview(next=>{next.entries=incoming.entries;next.reviewer=incoming.reviewer;})){render();toast('Review annotations imported. No source status was changed.');}}catch(error){toast('Import refused: '+error.message);}});
$('detail').addEventListener('submit',e=>e.preventDefault());
$('detail').addEventListener('cancel',e=>{e.preventDefault();closeDetail();});
$('globalSearch').addEventListener('input',e=>{searchFocus=0;renderSearch(e.target.value);});
$('globalSearch').addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();searchFocus=Math.max(0,Math.min(searchResults.length-1,searchFocus+(e.key==='ArrowDown'?1:-1)));$('searchResults').querySelectorAll('.command-item').forEach((el,i)=>el.classList.toggle('focused',i===searchFocus));$('searchResults').querySelectorAll('.command-item')[searchFocus]?.scrollIntoView({block:'nearest'});}if(e.key==='Enter'&&searchResults[searchFocus]){e.preventDefault();const item=searchResults[searchFocus];$('command').close();openRecord(item.type,item.r.id);}});
$('searchButton').addEventListener('click',startSearch);
$('menuButton').addEventListener('click',()=>{const on=!$('sidebar').classList.contains('open');$('sidebar').classList.toggle('open',on);$('overlay').classList.toggle('visible',on);$('menuButton').setAttribute('aria-expanded',String(on));if(on)$('sidebar').querySelector('.nav-item.active')?.focus();});
$('overlay').addEventListener('click',()=>{closeMenu();$('menuButton').focus();});
$('themeButton').addEventListener('click',()=>{dark=!dark;document.body.classList.toggle('dark',dark);$('themeButton').innerHTML=ic(dark?'sun':'moon');$('themeButton').setAttribute('aria-label',dark?'Switch to light appearance':'Switch to dark appearance');});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&$('sidebar').classList.contains('open')){const links=[...$('sidebar').querySelectorAll('a,button')];const first=links[0],last=links.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName);if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();startSearch();}else if(e.key==='/'&&!editing&&!$('about').open){e.preventDefault();startSearch();}else if(e.key==='Escape'&&$('sidebar').classList.contains('open')){closeMenu();$('menuButton').focus();}});
window.addEventListener('storage',e=>{if(e.key===STORE&&persistent){storageConflict=true;render(true);toast('Another tab changed the saved workspace. Reload it before writing.');}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('afterprint',()=>document.body.classList.remove('review-print'));
window.addEventListener('hashchange',()=>{try{routeChanged();}catch(error){toast('The route could not be read. Returning to the overview.');skipRouteGuard=true;location.hash='overview';}});
routeChanged();
